	private async UniTask<bool> DealDamageToEnvCard(UICardSimpleControl cardControl, int damage, int envIndex, EEffectType effectType = EEffectType.Damage)
	{
		cardControl.CallCardTakeDamage(damage, effectType);

		if (cardControl.CardData.currentHealth <= 0 && cardControl.CardType == ECardType.monster)
		{

			float delayTime = cardControl.CardEffect?.OnDead() ?? 0.5f;
			await UniTask.WaitForSeconds(delayTime);
			RemoveEnvCard(envIndex, cardControl);

			return true;
		}

		return false;
	}

	async void BoomEnvCard(object[] paraArray)
	{
		int envIndex = (int)paraArray[0];
		int damage = (int)paraArray[1];
		UICardSimpleControl cardControl = paraArray.Length > 2 ? (UICardSimpleControl)paraArray[2] : null;

		if (envIndex == -1)
		{
			envIndex = FindRandomEnemy();
			if (envIndex == -1)
			{
				return;
			}
		}
		Debug.Log("BoomEnvCard: envIndex = " + envIndex);
		foreach (var kvp in m_EnvCardDict)
		{
			Debug.Log("BoomEnvCard: envIndex = " + kvp.Key + " " + kvp.Value.Count);
		}


		int[] indices = { envIndex - 1, envIndex, envIndex + 1 };
		for (int i = 0; i < indices.Length; i++)
		{
			int index = indices[i];
			if (m_EnvCardDict.TryGetValue(index, out List<UICardSimpleControl> cardList))
			{
				if (cardList != null && cardList.Count > 0)
				{
					UICardSimpleControl lastCard = cardList[cardList.Count - 1];
					await DealDamageToEnvCard(lastCard, damage, index, EEffectType.Boom);
				}
			}
		}

		if (cardControl != null)
		{
			RemoveBagCard(cardControl.CardType, cardControl).Forget();
		}
	}

	private int FindRandomEnemy()
	{
		List<int> enemyIndices = new List<int>();
		foreach (var kvp in m_EnvCardDict)
		{
			if (kvp.Value != null && kvp.Value.Count > 0)
			{
				UICardSimpleControl lastCard = kvp.Value[kvp.Value.Count - 1];
				if (lastCard != null && lastCard.gameObject.activeSelf && lastCard.CardType == ECardType.monster)
				{
					enemyIndices.Add(kvp.Key);
				}
			}
		}
		if (enemyIndices.Count == 0)
		{
			return -1;
		}
		return enemyIndices[Random.Range(0, enemyIndices.Count)];
	}

