	async void MoveCard(object[] paraArray)
	{
		bool isEnv = (bool)paraArray[0];
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[1];
		cardControl.SetMoving(true);
		if (isEnv)
		{
			ECardType cardType = cardControl.CardType;

			Vector3 startWorldPos = cardControl.CacheTrans.parent.position;
			Vector3 startScale = Vector3.one;

			RemoveEnvCardFromDict(cardControl.EnvIndex, cardControl);
			AddBagCard(cardType, cardControl, true);
			cardControl.CardEffect?.OnEnterBag();
			//await UniTask.WaitForSeconds(delayTime);

			VerticalLayoutGroup layout = null;
			switch (cardType)
			{
				case ECardType.attack:
					layout = m_View.AttackPanel;
					break;
				case ECardType.defence:
					layout = m_View.DefencePanel;
					break;
				case ECardType.skill:
					layout = m_View.SkillPanel;
					break;
				case ECardType.item:
					layout = m_View.ItemPanel;
					break;
				default:
					return;
			}

			Vector3 endScale = new Vector3(0.8f, 0.8f, 1.0f);
			float duration = .2f;
			Vector3 endPos = layout.transform.position;

			m_MoveCardDelayAction.AddAnimDelayAction(
				(cancellationToken) => MoveCardAnimation(cardControl, startWorldPos, endPos, startScale, endScale, duration, layout, cancellationToken),
				() =>
				{
					cardControl.CacheTrans.position = endPos;
					cardControl.CacheTrans.localScale = endScale;
					layout.enabled = true;
					cardControl.SetMoving(false);
				}
			);
		}
	}

	private async UniTask MoveCardAnimation(UICardSimpleControl cardControl, Vector3 startPos, Vector3 endPos, Vector3 startScale, Vector3 endScale, float duration, VerticalLayoutGroup layout, CancellationToken cancellationToken)
	{
		layout.enabled = false;
		cardControl.CacheTrans.SetParent(layout.transform);

		Debug.Log("MoveCardAnimation: startPos = " + startPos + ", endPos = " + endPos + ", startScale = " + startScale + ", endScale = " + endScale + ", duration = " + duration);
		float elapsed = 0f;
		while (elapsed < duration)
		{
			cancellationToken.ThrowIfCancellationRequested();
			elapsed += Time.deltaTime;
			float t = elapsed / duration;

			cardControl.CacheTrans.position = Vector3.Lerp(startPos, endPos, t);
			cardControl.CacheTrans.localScale = Vector3.Lerp(startScale, endScale, t);

			Debug.Log($"MoveCard Animation - Position: {cardControl.CacheTrans.position}, Scale: {cardControl.CacheTrans.localScale}, t: {t}");

			await UniTask.Yield();
		}
	}

	async void TakeEnemyDamage(object[] paraArray)
	{
		UICardSimpleControl enemyCardControl = (UICardSimpleControl)paraArray[0];
		int attackCount = (int)paraArray[1];
		int envIndex = (int)paraArray[2];
		UICardSimpleControl attackCardControl = GetLastBagCard(ECardType.attack);
		if (attackCardControl == null)
		{
			attackCardControl = GetFistCard();
		}
		attackCount += attackCardControl.CardEffect?.GetEffectValue(EEffectType.ExtraTime) ?? 0;
		Card attackCard = attackCardControl.CardData;
		int damage = attackCard.currentAttack + attackCardControl.CardEffect?.GetEffectValue(EEffectType.Damage) ?? 0;

		float delayTime;

		for (int i = 0; i < attackCount; i++)
		{
			delayTime = attackCardControl.CardEffect?.OnDealDamage() ?? 0.5f;
			await UniTask.WaitForSeconds(delayTime);

			if (await DealDamageToEnvCard(enemyCardControl, damage, envIndex))
			{
				delayTime = attackCardControl.CardEffect?.OnKill() ?? 0.5f;
				await UniTask.WaitForSeconds(delayTime);
				break;
			}
			else
			{
				int enemyAttack = enemyCardControl.CardData.currentAttack;
				YActionSystem.Instance.DispatchAction(EActionId.TakePlayerDamage, enemyAttack, enemyCardControl, envIndex);
			}
		}
		delayTime = attackCardControl.CardEffect?.UseAttack() ?? 0.5f;
		await UniTask.WaitForSeconds(delayTime);
		RemoveBagCard(ECardType.attack, attackCardControl).Forget();
	}

	async void TakePlayerDamage(object[] paraArray)
	{
		int enemyAttack = (int)paraArray[0];
		UICardSimpleControl enemyCardControl = (UICardSimpleControl)paraArray[1];
		int envIndex = (int)paraArray[2];

		int defenceValue = 0;
		UICardSimpleControl defenceCardControl = GetLastBagCard(ECardType.defence);
		if (defenceCardControl != null)
		{
			float delayTime = defenceCardControl.CardEffect?.UseDefence() ?? 0.5f;
			await UniTask.WaitForSeconds(delayTime);
			defenceValue = defenceCardControl.CardData.currentDefence;
		}
		int damage = 0;
		if (defenceValue < enemyAttack)
		{
			damage = enemyAttack - defenceValue;
		}
		m_DataJoeyPlayer.playerHealth -= damage;
		if (m_DataJoeyPlayer.playerHealth < 0)
		{
			m_DataJoeyPlayer.playerHealth = 0;
		}
		OnHPChanged(m_DataJoeyPlayer.playerHealth);
		OnAttackChanged(m_DataJoeyPlayer.playerAttack);
		OnDefenceChanged(m_DataJoeyPlayer.playerDefence);

		if (defenceCardControl != null)
		{
			int reflectDamage = defenceCardControl.CardEffect?.GetEffectValue(EEffectType.ReflectDamage) ?? 0;
			if (reflectDamage > 0)
			{
				await AttackSpecialEnemy(enemyCardControl, reflectDamage, envIndex);
			}
			RemoveBagCard(ECardType.defence, defenceCardControl).Forget();
		}

		if (m_DataJoeyPlayer.playerHealth <= 0)
		{
			if (m_GameOverControl == null)
			{
				m_GameOverControl = this.Asset.OpenUI<UIGameOverControl>();
			}
			else
			{
				m_GameOverControl.gameObject.SetActive(true);
			}
		}
	}

	async void UseBagCard(object[] paraArray)
	{
		UICardSimpleControl cardControl = (UICardSimpleControl)paraArray[0];
		ECardType cardType = cardControl.CardType;
		float delayTime = 0f;

		if (cardType == ECardType.skill)
		{
			delayTime = cardControl.CardEffect?.UseSkill() ?? 0.5f;
		}
		else if (cardType == ECardType.item)
		{
